17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.List;
20	import java.util.Locale;
21	import java.util.regex.Pattern;
22	
23	import org.springframework.samples.petclinic.model.Owner;
24	import org.springframework.samples.petclinic.model.Sha256Hex;
25	import org.springframework.samples.petclinic.service.ClinicService;
26	import org.springframework.stereotype.Component;
27	
28	/**
29	 * Groups owners into households and derives a household's stable shared identifier.
30	 * <p>
31	 * Two owners belong to the same household when they carry the same last name and the same
32	 * address. The last name is compared leniently: surrounding whitespace is trimmed, internal
33	 * runs of whitespace are collapsed to a single space and letters are compared without
34	 * regard to case, so values that differ only in spacing or capitalisation are treated as
35	 * equal. The address is compared in its canonical {@link AddressNormalizer normalized} form,
36	 * the same form under which it is stored and returned.
37	 */
38	@Component
39	public class HouseholdMatcher {
40	
41	    /** Runs of whitespace collapsed to a single space before comparison. */
42	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
43	
44	    private final ClinicService clinicService;
45	
46	    private final AddressNormalizer addressNormalizer;
47	
48	    public HouseholdMatcher(ClinicService clinicService, AddressNormalizer addressNormalizer) {
49	        this.clinicService = clinicService;
50	        this.addressNormalizer = addressNormalizer;
51	    }
52	
53	    /**
54	     * Returns the already-stored owners that share {@code candidate}'s household under the
55	     * lenient comparison described above. The candidate itself is not yet stored, so it is
56	     * never included.
57	     *
58	     * @param candidate the owner being created
59	     * @return existing household members, possibly empty
60	     */
61	    public List<Owner> findMembers(Owner candidate) {
62	        String key = householdKey(candidate);
63	        return clinicService.findAllOwners().stream()
64	            .filter(existing -> householdKey(existing).equals(key))
65	            .toList();
66	    }
67	
68	    /**
69	     * The stable identifier for {@code candidate}'s household, derived deterministically
70	     * from its (normalised) last name and address so that every member resolves to the
71	     * same value.
72	     *
73	     * @param candidate an owner in the household
74	     * @return a non-blank household identifier
75	     */
76	    public String householdId(Owner candidate) {
77	        return Sha256Hex.prefix(householdKey(candidate), 12);
78	    }
79	
80	    private String householdKey(Owner owner) {
81	        return normalizeName(owner.getLastName()) + "\n" + addressNormalizer.normalize(owner.getAddress());
82	    }
83	
84	    private String normalizeName(String value) {
85	        if (value == null) {
86	            return "";
87	        }
88	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
89	    }
90	}
