39	     * Assigns {@code owner}'s possible-duplicate flag and, when it softly matches an
40	     * existing owner, the matched owner's id.
41	     *
42	     * @param owner the owner being created
43	     */
44	    public void assign(Owner owner) {
45	        Optional<Owner> match = possibleDuplicateMatcher.findMatch(owner);
46	        owner.setPossibleDuplicate(match.isPresent());
47	        owner.setPossibleDuplicateOf(match.map(Owner::getId).orElse(null));
48	    }
